/**
 * Copyable code block. Pure presentation: the snippet itself is generated by
 * `snippets.ts`, so what a visitor copies always matches what they see live.
 */

import { useEffect, useRef, useState } from 'react';
import { Check, Copy } from 'lucide-react';
import { copyText } from '../ui/utils';

export interface CodeBlockProps {
  code: string;
  /** Shown in the block header, e.g. `src/Root.tsx` or `terminal`. */
  title?: string;
  /** Accessible name of the copy button. */
  label?: string;
  onCopied?: (ok: boolean) => void;
  className?: string;
}

export function CodeBlock({ code, title, label = 'Copy snippet', onCopied, className = '' }: CodeBlockProps) {
  const [copied, setCopied] = useState(false);
  const timer = useRef<number | undefined>(undefined);

  useEffect(() => () => window.clearTimeout(timer.current), []);

  const copy = async () => {
    const ok = await copyText(code);
    onCopied?.(ok);
    if (!ok) return;
    setCopied(true);
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => setCopied(false), 1600);
  };

  return (
    <div className={`docs-code ${className}`}>
      <div className="docs-code-head">
        <span className="docs-code-title">{title ?? 'tsx'}</span>
        <button
          type="button"
          className="docs-code-copy"
          onClick={copy}
          aria-label={copied ? `${label} — copied` : label}
        >
          {copied ? <Check size={13} /> : <Copy size={13} />}
          {copied ? 'Copied' : 'Copy'}
        </button>
      </div>
      <pre tabIndex={0}><code>{code}</code></pre>
    </div>
  );
}
